SELECT * FROM CUSTOMER LIMIT 5 ;

-- TOTAL REVENUE GENERATED BY MALE AND FEMALE CUSTOMERS

SELECT GENDER,SUM(PURCHASE_AMOUNT_USD) AS  REVENEUE FROM CUSTOMER
GROUP BY GENDER;

--CUSTOMERS USED A DISCOUNT BUT STILL SPEND MORE THAN AVERAGE PURCHASE AMOUNT 


SELECT CUSTOMER_ID,PURCHASE_AMOUNT_USD FROM CUSTOMER 
WHERE  DISCOUNT_APPLIED ='Yes' AND 
PURCHASE_AMOUNT_USD > (SELECT AVG(PURCHASE_AMOUNT_USD) FROM CUSTOMER);


--top 5 product with highest average review writing 
SELECT ITEM_PURCHASED,ROUND(AVG(REVIEW_RATING ::NUMERIC),2) AS AVERAGE_REVIEW_RATING FROM CUSTOMER 
GROUP BY ITEM_PURCHASED
ORDER BY AVERAGE_REVIEW_RATING DESC LIMIT 5;

--COMPARE THE AVERAGE PURCHASE AMOUNT AND STANDDARD AND EXPRESS AND STANDARD SHIPPING 

SELECT SHIPPING_TYPE, ROUND(AVG(PURCHASE_AMOUNT_USD),2) AS AVERAGE_AMOUNT FROM CUSTOMER
WHERE   SHIPPING_TYPE='Express' OR SHIPPING_TYPE='Standard'
GROUP BY SHIPPING_TYPE 
ORDER BY AVERAGE_AMOUNT DESC ;

----Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.

SELECT SUBSCRIPTION_STATUS , COUNT(CUSTOMER_ID) AS TOTAL_CUSTOMER,
ROUND(AVG(PURCHASE_AMOUNT_USD),2) AVG_SPEND ,
ROUND(SUM(PURCHASE_AMOUNT_USD),2) AS TOTAL_REVENUE
FROM CUSTOMER
GROUP BY SUBSCRIPTION_STATUS
ORDER BY TOTAL_REVENUE,AVG_SPEND DESC;


-- 6  PRODUCTS HAVE HIGHEST PERCENTAGE PURCHASES WITH DISCOUNT APPLIED
SELECT ITEM_PURCHASED ,
ROUND(100 * SUM(CASE WHEN DISCOUNT_APPLIED='Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS DISCOUNT_RATE
FROM CUSTOMER
GROUP BY ITEM_PURCHASED 
ORDER BY DISCOUNT_RATE DESC
LIMIT 5;





-- Q7. SEGMENT CUSTOMERS INTO NEW, RETURNING, AND LOYAL BASED ON THEIR TOTAL
-- NUMBER OF PREVIOUS PURCHASES, AND SHOW THE COUNT OF EACH SEGMENT.

WITH CUSTOMER_TYPE AS (
    SELECT CUSTOMER_ID, PREVIOUS_PURCHASES,
    CASE 
        WHEN PREVIOUS_PURCHASES = 1 THEN 'NEW'
        WHEN PREVIOUS_PURCHASES BETWEEN 2 AND 10 THEN 'RETURNING'
        ELSE 'LOYAL'
    END AS CUSTOMER_SEGMENT
    FROM CUSTOMER
)

SELECT CUSTOMER_SEGMENT, COUNT(*) AS "NUMBER OF CUSTOMERS"
FROM CUSTOMER_TYPE
GROUP BY CUSTOMER_SEGMENT;


-- Q8. WHAT ARE THE TOP 3 MOST PURCHASED PRODUCTS WITHIN EACH CATEGORY?

WITH ITEM_COUNTS AS (
    SELECT CATEGORY,
           ITEM_PURCHASED,
           COUNT(CUSTOMER_ID) AS TOTAL_ORDERS,
           ROW_NUMBER() OVER (
               PARTITION BY CATEGORY
               ORDER BY COUNT(CUSTOMER_ID) DESC
           ) AS ITEM_RANK
    FROM CUSTOMER
    GROUP BY CATEGORY, ITEM_PURCHASED
)

SELECT ITEM_RANK, CATEGORY, ITEM_PURCHASED, TOTAL_ORDERS
FROM ITEM_COUNTS
WHERE ITEM_RANK <= 3;


-- Q9. ARE CUSTOMERS WHO ARE REPEAT BUYERS (MORE THAN 5 PREVIOUS PURCHASES)
-- ALSO LIKELY TO SUBSCRIBE?

SELECT SUBSCRIPTION_STATUS,
       COUNT(CUSTOMER_ID) AS REPEAT_BUYERS
FROM CUSTOMER
WHERE PREVIOUS_PURCHASES > 5
GROUP BY SUBSCRIPTION_STATUS;


-- Q10. WHAT IS THE REVENUE CONTRIBUTION OF EACH AGE GROUP?

SELECT 
    AGE_GROUP,
    SUM(PURCHASE_AMOUNT_USD) AS TOTAL_REVENUE
FROM CUSTOMER
GROUP BY AGE_GROUP
ORDER BY TOTAL_REVENUE DESC;

